interface ExportContract { String export(); }
abstract class StatefulBase {
    final String id;
    StatefulBase(String id) { this.id = id; }
}
class CombinedProduct extends StatefulBase implements ExportContract {
    CombinedProduct(String id) { super(id); }
    public String export() { return "export:" + id; }
}
public class AbstractInterfaceRefactorDemo {
    public static void main(String[] args) { System.out.println(new CombinedProduct("O1").export()); }
}
